"""Auto-detects log format per file and builds the engine's ``LogSource`` list.

Sniffing reuses the real parsers' public ``parse_line`` rather than their
private regexes, so a sniff success guarantees the file will actually parse
(it also validates the timestamp format, not just line shape). This keeps
format detection a CLI-layer concern -- the ``engine`` package stays
format-agnostic, per its own documented boundary.
"""

from __future__ import annotations

from collections.abc import Sequence
from datetime import UTC, datetime
from pathlib import Path
from typing import Literal

from engine import CombinedLogParser, LogSource, MalformedLineError, SyslogAuthParser, WebLogEntry, parse_file

LogFormat = Literal["web", "auth"]


def _first_nonblank_line(path: Path) -> str | None:
    try:
        with path.open("r", encoding="utf-8", errors="replace") as handle:
            for line in handle:
                if line.strip():
                    return line
    except OSError:
        return None
    return None


def detect_format(path: Path) -> LogFormat | None:
    """Sniff ``path``'s first non-blank line against known formats.

    Returns ``None`` if the file is empty, unreadable, or matches neither
    format -- the caller decides whether that is fatal.
    """
    line = _first_nonblank_line(path)
    if line is None:
        return None
    try:
        CombinedLogParser().parse_line(line, 1)
    except MalformedLineError:
        pass
    else:
        return "web"
    try:
        SyslogAuthParser().parse_line(line, 1)
    except MalformedLineError:
        return None
    return "auth"


def _reference_time(web_paths: Sequence[Path]) -> datetime:
    """Anchor auth-log year resolution to the newest timestamp among detected
    web logs in this run, falling back to "now" if there are none (generalizes
    ``scripts/run_demo.py``'s single-file helper of the same name to N files).
    """
    latest: datetime | None = None
    for path in web_paths:
        for item in parse_file(path, CombinedLogParser()):
            if isinstance(item, WebLogEntry) and (latest is None or item.timestamp > latest):
                latest = item.timestamp
    return latest if latest is not None else datetime.now(UTC)


def build_log_sources(paths: Sequence[Path]) -> tuple[list[LogSource], list[Path]]:
    """Detect each path's format and build matching ``LogSource``s.

    Returns ``(sources, skipped)``; ``skipped`` holds paths matching neither
    known format (including empty/unreadable files).
    """
    detected: dict[Path, LogFormat] = {}
    skipped: list[Path] = []
    for path in paths:
        fmt = detect_format(path)
        if fmt is None:
            skipped.append(path)
        else:
            detected[path] = fmt

    web_paths = [p for p, fmt in detected.items() if fmt == "web"]
    reference_time = _reference_time(web_paths)

    sources = [
        LogSource(
            path=str(path),
            parser=(
                CombinedLogParser(source=path.stem)
                if fmt == "web"
                else SyslogAuthParser(source=path.stem, reference_time=reference_time)
            ),
        )
        for path, fmt in detected.items()
    ]
    return sources, skipped

"""Cross-rule correlation.

Groups findings by IP and clusters those close in time into ``Incident``s. An
incident forms only for genuine multi-signal activity (≥2 distinct rules OR ≥2
sources for the same IP) — a single rule's repeated findings never do.

See docs/engine-plan.md §7.
"""

from __future__ import annotations

from collections import defaultdict
from collections.abc import Iterable
from datetime import datetime, timedelta
import hashlib

from constants import DEFAULT_CORRELATION_WINDOW_MINUTES
from models import Finding, Incident, Severity


class Correlator:
    """Stateless correlator; clusters findings per IP within a time window."""

    def __init__(self, window: timedelta = timedelta(minutes=DEFAULT_CORRELATION_WINDOW_MINUTES)) -> None:
        self.window = window

    def correlate(self, findings: Iterable[Finding]) -> list[Incident]:
        by_ip: dict[str | None, list[Finding]] = defaultdict(list)
        for f in findings:
            by_ip[f.source_ip].append(f)

        incidents: list[Incident] = []
        for ip, ip_findings in by_ip.items():
            if ip is None:
                continue  # can't meaningfully correlate findings with no IP
            ip_findings.sort(key=lambda f: f.first_seen)
            for cluster in self._cluster(ip_findings):
                incident = self._build_incident(ip, cluster)
                if incident is not None:
                    incidents.append(incident)

        incidents.sort(key=lambda i: (i.first_seen, i.source_ip or ""))
        return incidents

    def _cluster(self, findings: list[Finding]) -> list[list[Finding]]:
        """Greedily group findings whose gap from the running span <= window."""
        clusters: list[list[Finding]] = []
        current: list[Finding] = []
        current_end: datetime | None = None
        for f in findings:
            if current_end is not None and f.first_seen - current_end <= self.window:
                current.append(f)
                current_end = max(current_end, f.last_seen)
            else:
                if current:
                    clusters.append(current)
                current = [f]
                current_end = f.last_seen
        if current:
            clusters.append(current)
        return clusters

    def _build_incident(self, ip: str, cluster: list[Finding]) -> Incident | None:
        rule_ids = {f.rule_id for f in cluster}
        sources = {s for f in cluster for s in f.sources}
        if len(rule_ids) < 2 and len(sources) < 2:
            return None

        first_seen = min(f.first_seen for f in cluster)
        last_seen = max(f.last_seen for f in cluster)
        severity = self._escalate(max(f.severity for f in cluster))

        # sha1 for a short deterministic display id, not a security use of the hash.
        incident_id = (
            "INC-"
            + hashlib.sha1(  # noqa: S324
                (f"{ip}|{first_seen.isoformat()}|" + ",".join(sorted(rule_ids))).encode()
            ).hexdigest()[:10]
        )

        return Incident(
            incident_id=incident_id,
            title=f"Correlated activity from {ip}",
            severity=severity,
            source_ip=ip,
            first_seen=first_seen,
            last_seen=last_seen,
            findings=list(cluster),
            narrative=self._narrative(ip, cluster, rule_ids, sources, first_seen, last_seen),
        )

    @staticmethod
    def _escalate(max_severity: Severity) -> Severity:
        """One level above the max child severity, capped at CRITICAL."""
        members = sorted(Severity)
        idx = members.index(max_severity)
        return members[min(idx + 1, len(members) - 1)]

    @staticmethod
    def _narrative(
        ip: str,
        cluster: list[Finding],
        rule_ids: set[str],
        sources: set[str],
        first_seen: datetime,
        last_seen: datetime,
    ) -> str:
        span = last_seen - first_seen
        titles = sorted({f.title for f in cluster})
        return (
            f"{ip} triggered {len(cluster)} findings across {len(rule_ids)} rule(s) "
            f"({', '.join(titles)}) over {', '.join(sorted(sources))} "
            f"within {span} ({first_seen.isoformat()} → {last_seen.isoformat()})."
        )
